                    Card { SettingsRow(title: store.t("Questionnaire", "觀察問卷"), icon: "book", value: "\(store.data.reviewedCount)/\(store.questions.count)") }
                }.buttonStyle(.plain).accessibilityIdentifier("openQuestionnaire")
