                Button(role: .destructive) { Task { _ = await community.signOut() } } label: {
                    Text(community.busy ? store.t("Logging out…", "正在登出…") : store.t("Log out", "登出"))
                        .frame(maxWidth: .infinity, minHeight: 48, alignment: .leading)
